{"code":"import pulp
pieces=[(9,3.15),(13,3.00),(16,2.85),(17,2.40),(16,1.40),(8,1.05)]
counts=[p[0] for p in pieces]
lengths=[p[1] for p in pieces]
max_counts=[min(count, int(6//length)) for count,length in zip(counts,lengths)]
patterns=[]
for a in range(max_counts[0]+1):
 for b in range(max_counts[1]+1):
  for c in range(max_counts[2]+1):
   for d in range(max_counts[3]+1):
    for e in range(max_counts[4]+1):
     for f in range(max_counts[5]+1):
      total=a*3.15+b*3.0+c*2.85+d*2.4+e*1.4+f*1.05
      if total<=6+1e-9 and (a,b,c,d,e,f)!=(0,0,0,0,0,0):
        patterns.append((a,b,c,d,e,f))
prob=pulp.LpProblem('cut',pulp.LpMinimize)
x=[pulp.LpVariable(f'x{i}', lowBound=0, cat='Integer') for i in range(len(patterns))]
prob+=pulp.lpSum(x)
for idx in range(6):
 prob+=pulp.lpSum(x[i]*patterns[i][idx] for i in range(len(patterns)))>=counts[idx]
prob.solve(pulp.PULP_CBC_CMD(msg=False))
print(pulp.value(prob.objective))
"}

