{"code":"import pulp
lengths = [3.20]*4 + [3.00]*8 + [2.70]*4 + [2.55]*13 + [2.00]*17 + [1.15]*7 + [1.05]*9 + [1.00]*9
n=len(lengths)
max_bars=int(sum(lengths)/6)+2
x = {}
for i in range(n):
    for j in range(max_bars):
        x[(i,j)] = pulp.LpVariable(f'x_{i}_{j}', cat='Binary')
prob=pulp.LpProblem('binpacking', pulp.LpMinimize)
# assign each piece
for i in range(n):
    prob+= pulp.lpSum(x[(i,j)] for j in range(max_bars))==1
# capacity
for j in range(max_bars):
    prob+= pulp.lpSum(lengths[i]*x[(i,j)] for i in range(n)) <=6
# used bars
used = {}
for j in range(max_bars):
    used[j]=pulp.LpVariable(f'used_{j}', cat='Binary')
    prob+= used[j] >= pulp.lpSum(x[(i,j)] for i in range(n))/n
prob+= pulp.lpSum(used[j] for j in range(max_bars))
prob.solve(pulp.PULP_CBC_CMD(msg=False))
print('status', pulp.LpStatus[prob.status])
print('bars used', sum(used[j].value() for j in range(max_bars)))
"}

